/// ONE CONNECTOR. Everything a reader learns about it; nothing an operator can change is carried as a field.
#[derive(Clone, Debug, PartialEq)]
pub struct Connector {
	/// From 1.
	pub number: u8,
	pub capabilities: Capabilities,
	pub partner: PartnerKind,
	pub orientation: Orientation,
	pub power_role: Option<PowerRole>,
	pub data_role: Option<DataRole>,
	pub operation_mode: OperationMode,
	pub contract: Option<Contract>,
	pub typec_current: TypecCurrent,
	/// The partner's source offers, at most eleven: Power Delivery's seven standard positions and four extended.
	pub offers: Vec<Offer>,
	pub cable: Option<Cable>,
	pub modes: Vec<AlternateMode>,
	pub displayport: Option<Displayport>,
	pub last_refusal: Option<RefusedRequest>,
	/// Whether the transport is answering. False while a policy manager is silent or being reset: what is carried
	/// is the last that was read.
	pub answering: bool,
}

impl Connector {
	pub fn encode(&self, out: &mut [u8]) -> Option<usize> {
		let mut w = SliceWriter::new(out);
		self.write(&mut w)?;
		// `finish` refuses while a capability is recorded, because returning the
		// length alone would drop it.
		w.finish()
	}
	pub fn encode_vec(&self) -> Option<Vec<u8>> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		// `into_inner` refuses while a capability is recorded, because returning
		// the bytes alone would drop it.
		w.into_inner()
	}
	pub fn encode_message(&self) -> Option<(Vec<u8>, Handles)> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		Some(w.into_message())
	}
	pub fn decode(bytes: &[u8]) -> Option<Connector> {
		let mut r = Reader::new(bytes);
		let value = Connector::read(&mut r)?;
		r.finish()?;
		Some(value)
	}
	pub fn decode_message(bytes: &[u8], handles: &mut Handles) -> Option<Connector> {
		let mut r = Reader::with_handles(bytes, handles);
		let value = Connector::read(&mut r)?;
		r.finish()?;
		// The frame is good, so the capabilities it carried are the value's now. A
		// refusal above leaves them in the caller's list, which is the half that closes.
		handles.clear();
		Some(value)
	}
	pub fn write<W: Sink>(&self, w: &mut W) -> Option<()> {
		w.u8(self.number)?;
		self.capabilities.write(w)?;
		self.partner.write(w)?;
		self.orientation.write(w)?;
		match &self.power_role {
			Some(v1) => {
				w.u8(1)?;
				v1.write(w)?;
			}
			None => {
				w.u8(0)?;
			}
		}
		match &self.data_role {
			Some(v2) => {
				w.u8(1)?;
				v2.write(w)?;
			}
			None => {
				w.u8(0)?;
			}
		}
		self.operation_mode.write(w)?;
		match &self.contract {
			Some(v3) => {
				w.u8(1)?;
				v3.write(w)?;
			}
			None => {
				w.u8(0)?;
			}
		}
		self.typec_current.write(w)?;
		if self.offers.len() > u16::MAX as usize {
			return None;
		}
		w.u16(self.offers.len() as u16)?;
		for v4 in self.offers.iter() {
			v4.write(w)?;
		}
		match &self.cable {
			Some(v5) => {
				w.u8(1)?;
				v5.write(w)?;
			}
			None => {
				w.u8(0)?;
			}
		}
		if self.modes.len() > u16::MAX as usize {
			return None;
		}
		w.u16(self.modes.len() as u16)?;
		for v6 in self.modes.iter() {
			v6.write(w)?;
		}
		match &self.displayport {
			Some(v7) => {
				w.u8(1)?;
				v7.write(w)?;
			}
			None => {
				w.u8(0)?;
			}
		}
		match &self.last_refusal {
			Some(v8) => {
				w.u8(1)?;
				v8.write(w)?;
			}
			None => {
				w.u8(0)?;
			}
		}
		w.boolean(self.answering)?;
		Some(())
	}
	pub fn read(r: &mut Reader) -> Option<Connector> {
		let number = r.u8()?;
		let capabilities = Capabilities::read(r)?;
		let partner = PartnerKind::read(r)?;
		let orientation = Orientation::read(r)?;
		let power_role = if r.tag()? { Some(PowerRole::read(r)?) } else { None };
		let data_role = if r.tag()? { Some(DataRole::read(r)?) } else { None };
		let operation_mode = OperationMode::read(r)?;
		let contract = if r.tag()? { Some(Contract::read(r)?) } else { None };
		let typec_current = TypecCurrent::read(r)?;
		let offers = {
			let v9 = r.u16()? as usize;
			let v9 = (v9 <= 11).then_some(v9)?;
			let mut v10 = Vec::new();
			v10.try_reserve_exact(v9).ok()?;
			for _ in 0..v9 {
				v10.push(Offer::read(r)?);
			}
			v10
		};
		let cable = if r.tag()? { Some(Cable::read(r)?) } else { None };
		let modes = {
			let v11 = r.u16()? as usize;
			let v11 = (v11 <= 16).then_some(v11)?;
			let mut v12 = Vec::new();
			v12.try_reserve_exact(v11).ok()?;
			for _ in 0..v11 {
				v12.push(AlternateMode::read(r)?);
			}
			v12
		};
		let displayport = if r.tag()? { Some(Displayport::read(r)?) } else { None };
		let last_refusal = if r.tag()? { Some(RefusedRequest::read(r)?) } else { None };
		let answering = r.boolean()?;
		Some(Connector { number, capabilities, partner, orientation, power_role, data_role, operation_mode, contract, typec_current, offers, cable, modes, displayport, last_refusal, answering })
	}
}

