	pub fn to_json_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("\"transport\":");
		self.transport.to_json_into(out);
		out.push(',');
		out.push_str("\"sink\":");
		if self.sink {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push(',');
		out.push_str("\"source\":");
		if self.source {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push(',');
		out.push_str("\"data-device\":");
		if self.data_device {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push(',');
		out.push_str("\"data-host\":");
		if self.data_host {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push(',');
		out.push_str("\"power-delivery\":");
		if self.power_delivery {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push(',');
		out.push_str("\"ucsi-version\":");
		let _ = write!(out, "{}", self.ucsi_version);
		out.push(',');
		out.push_str("\"ucsi-features\":");
		let _ = write!(out, "{}", self.ucsi_features);
		out.push(',');
		out.push_str("\"alternate-mode-override\":");
		if self.alternate_mode_override {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push('}');
	}
	pub fn to_text_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("transport=");
		self.transport.to_text_into(out);
		out.push_str(", ");
		out.push_str("sink=");
		if self.sink {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push_str(", ");
		out.push_str("source=");
		if self.source {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push_str(", ");
		out.push_str("data-device=");
		if self.data_device {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push_str(", ");
		out.push_str("data-host=");
		if self.data_host {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push_str(", ");
		out.push_str("power-delivery=");
		if self.power_delivery {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push_str(", ");
		out.push_str("ucsi-version=");
		let _ = write!(out, "{}", self.ucsi_version);
		out.push_str(", ");
		out.push_str("ucsi-features=");
		let _ = write!(out, "{}", self.ucsi_features);
		out.push_str(", ");
		out.push_str("alternate-mode-override=");
		if self.alternate_mode_override {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push('}');
	}
	pub fn to_cbor_into(&self, out: &mut Vec<u8>) {
		crate::codec::cbor::map(out, 9);
		crate::codec::cbor::text(out, "transport");
		self.transport.to_cbor_into(out);
		crate::codec::cbor::text(out, "sink");
		crate::codec::cbor::boolean(out, self.sink);
		crate::codec::cbor::text(out, "source");
		crate::codec::cbor::boolean(out, self.source);
		crate::codec::cbor::text(out, "data-device");
		crate::codec::cbor::boolean(out, self.data_device);
		crate::codec::cbor::text(out, "data-host");
		crate::codec::cbor::boolean(out, self.data_host);
		crate::codec::cbor::text(out, "power-delivery");
		crate::codec::cbor::boolean(out, self.power_delivery);
		crate::codec::cbor::text(out, "ucsi-version");
		crate::codec::cbor::uint(out, self.ucsi_version as u64);
		crate::codec::cbor::text(out, "ucsi-features");
		crate::codec::cbor::uint(out, self.ucsi_features as u64);
		crate::codec::cbor::text(out, "alternate-mode-override");
		crate::codec::cbor::boolean(out, self.alternate_mode_override);
	}
